/* "@name" -> name; an old emoji / symbol -> the SVG that replaces it; anything else (L1, A, OK, ...) -> "" and stays plain text */
const svgName=ic=>{if(!ic)return"";ic=String(ic);if(ic[0]==="@")return SVGI[ic.slice(1)]?ic.slice(1):"";return LEG[ic.replace(/\uFE0F/g,"")]||""};
