    const go=document.createElement(i===S.li?"span":"button");go.className=i===S.li?"lyon":"lygo";
    go.textContent=i===S.li?"Editing":"Edit";if(i!==S.li)go.onclick=()=>tryLayer(i);
    top.append(ch,nm,go);
