    act.append(ib("chevron-up","Move up",()=>moveLayer(i,-1),i===0),ib("chevron-down","Move down",()=>moveLayer(i,1),i===n-1),ib("u-trash","Delete this mode",()=>delLayer(i),n<2,"dng"));
    bot.append(tg,act);r.append(top,bot);box.appendChild(r);
