    const a=b._a=b.animate([{height:h+"px",opacity:1,transform:"none"},{height:"0px",opacity:0,transform:"translateY(-10px)"}],{duration:320,easing:"cubic-bezier(.65,0,.35,1)",fill:"forwards"});
